import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the same cooperative-tiled 2D convolution
# algorithm as the reference CuTe/CUDA kernel:
#   - 16x16 spatial output tile per block (256 threads)
#   - OC_TILE = 16 output channels per block
#   - shared memory caches an input patch (with halo) and a weight slice
#     for the current input channel, reused across the whole spatial tile
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.extern .shared .align 4 .b8 smem[];

.visible .entry conv2d_kernel(
    .param .u64 X_ptr,
    .param .u64 W_ptr,
    .param .u64 B_ptr,
    .param .u64 Y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation,
    .param .u32 groups,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 Cin_g,
    .param .u32 Cout_g,
    .param .u32 num_oc_tiles_per_group,
    .param .u32 total_oc_tiles,
    .param .u32 halo_h,
    .param .u32 halo_w,
    .param .u32 has_bias
)
{
    .reg .pred  %p<32>;
    .reg .b32   %r<200>;
    .reg .f32   %f<32>;
    .reg .b64   %rd<60>;

    // ---- load pointers ----
    ld.param.u64 %rd1, [X_ptr];
    cvta.to.global.u64 %rd2, %rd1;
    ld.param.u64 %rd3, [W_ptr];
    cvta.to.global.u64 %rd4, %rd3;
    ld.param.u64 %rd5, [B_ptr];
    cvta.to.global.u64 %rd6, %rd5;
    ld.param.u64 %rd7, [Y_ptr];
    cvta.to.global.u64 %rd8, %rd7;

    // ---- load scalars ----
    ld.param.u32 %r30, [N];
    ld.param.u32 %r31, [Cin];
    ld.param.u32 %r32, [H];
    ld.param.u32 %r33, [Win];
    ld.param.u32 %r34, [Cout];
    ld.param.u32 %r35, [K];
    ld.param.u32 %r36, [stride];
    ld.param.u32 %r37, [padding];
    ld.param.u32 %r38, [dilation];
    ld.param.u32 %r39, [groups];
    ld.param.u32 %r40, [Hout];
    ld.param.u32 %r41, [Wout];
    ld.param.u32 %r42, [Cin_g];
    ld.param.u32 %r43, [Cout_g];
    ld.param.u32 %r44, [num_oc_tiles_per_group];
    ld.param.u32 %r45, [total_oc_tiles];
    ld.param.u32 %r46, [halo_h];
    ld.param.u32 %r47, [halo_w];
    ld.param.u32 %r48, [has_bias];

    setp.ne.s32 %p17, %r48, 0;

    // ---- thread indices within 16x16 tile ----
    mov.u32 %r1, %tid.x;
    shr.u32 %r2, %r1, 4;
    and.b32 %r3, %r1, 15;

    // ---- decode blockIdx.z -> (n, group, oc_tile) ----
    mov.u32 %r4, %ctaid.z;
    div.s32 %r5, %r4, %r45;
    mul.lo.s32 %r6, %r5, %r45;
    sub.s32 %r7, %r4, %r6;

    div.s32 %r8, %r7, %r44;
    mul.lo.s32 %r9, %r8, %r44;
    sub.s32 %r10, %r7, %r9;

    shl.b32 %r11, %r10, 4;

    mul.lo.s32 %r12, %r8, %r43;
    add.s32 %r13, %r12, %r11;

    sub.s32 %r14, %r43, %r11;
    min.s32 %r15, %r14, 16;

    // ---- spatial tile origin & output coords ----
    mov.u32 %r16, %ctaid.y;
    shl.b32 %r17, %r16, 4;
    mov.u32 %r18, %ctaid.x;
    shl.b32 %r19, %r18, 4;

    add.s32 %r20, %r17, %r2;
    add.s32 %r21, %r19, %r3;

    setp.lt.s32 %p1, %r20, %r40;
    setp.lt.s32 %p2, %r21, %r41;
    and.pred  %p3, %p1, %p2;

    // ---- ih_base, iw_base ----
    mul.lo.s32 %r53, %r17, %r36;
    sub.s32 %r50, %r53, %r37;
    mul.lo.s32 %r54, %r19, %r36;
    sub.s32 %r51, %r54, %r37;

    // ---- ic_base ----
    mul.lo.s32 %r52, %r8, %r42;

    // ---- X batch pointer ----
    mul.lo.s32 %r60, %r31, %r32;
    mul.lo.s32 %r61, %r60, %r33;
    mul.wide.s32 %rd10, %r5, %r61;
    shl.b64 %rd11, %rd10, 2;
    add.s64 %rd12, %rd2, %rd11;

    // ---- Y batch pointer ----
    mul.lo.s32 %r62, %r34, %r40;
    mul.lo.s32 %r63, %r62, %r41;
    mul.wide.s32 %rd13, %r5, %r63;
    shl.b64 %rd14, %rd13, 2;
    add.s64 %rd15, %rd8, %rd14;

    // ---- shared memory layout ----
    mul.lo.s32 %r70, %r46, %r47;
    shl.b32 %r71, %r70, 2;
    mov.u32 %r72, smem;
    add.s32 %r73, %r72, %r71;

    mul.lo.s32 %r74, %r35, %r35;
    shl.b32 %r75, %r74, 4;

    // ---- init accumulators ----
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f4, 0f00000000;
    mov.f32 %f5, 0f00000000;
    mov.f32 %f6, 0f00000000;
    mov.f32 %f7, 0f00000000;
    mov.f32 %f8, 0f00000000;
    mov.f32 %f9, 0f00000000;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;

    mov.s32 %r80, 0;
L_IC_LOOP:
    setp.ge.s32 %p4, %r80, %r42;
    @%p4 bra L_IC_END;

    add.s32 %r81, %r52, %r80;
    mul.lo.s32 %r82, %r81, %r32;
    mul.lo.s32 %r82, %r82, %r33;
    mul.lo.s32 %r83, %r80, %r74;

    // ---- load input tile (with halo) into sX ----
    mov.s32 %r90, %r1;
L_LOADX_LOOP:
    setp.ge.s32 %p5, %r90, %r70;
    @%p5 bra L_LOADX_END;

    div.s32 %r91, %r90, %r47;
    mul.lo.s32 %r92, %r91, %r47;
    sub.s32 %r93, %r90, %r92;

    add.s32 %r94, %r50, %r91;
    add.s32 %r95, %r51, %r93;

    setp.lt.s32 %p6, %r94, 0;
    setp.ge.s32 %p7, %r94, %r32;
    or.pred  %p8, %p6, %p7;
    setp.lt.s32 %p9, %r95, 0;
    setp.ge.s32 %p10, %r95, %r33;
    or.pred  %p11, %p9, %p10;
    or.pred  %p12, %p8, %p11;

    mov.f32 %f17, 0f00000000;
    @%p12 bra L_LOADX_SKIP;

    mul.lo.s32 %r96, %r94, %r33;
    add.s32 %r97, %r82, %r96;
    add.s32 %r98, %r97, %r95;
    cvt.s64.s32 %rd21, %r98;
    shl.b64 %rd22, %rd21, 2;
    add.s64 %rd23, %rd12, %rd22;
    ld.global.f32 %f17, [%rd23];

L_LOADX_SKIP:
    shl.b32 %r99, %r90, 2;
    add.s32 %r100, %r72, %r99;
    st.shared.f32 [%r100], %f17;

    add.s32 %r90, %r90, 256;
    bra.uni L_LOADX_LOOP;
L_LOADX_END:

    // ---- load weight slice for OC_TILE channels into sW ----
    mov.s32 %r110, %r1;
L_LOADW_LOOP:
    setp.ge.s32 %p13, %r110, %r75;
    @%p13 bra L_LOADW_END;

    div.s32 %r111, %r110, %r74;
    mul.lo.s32 %r112, %r111, %r74;
    sub.s32 %r113, %r110, %r112;

    setp.ge.s32 %p14, %r111, %r15;
    mov.f32 %f18, 0f00000000;
    @%p14 bra L_LOADW_SKIP;

    add.s32 %r117, %r13, %r111;
    mul.lo.s32 %r118, %r117, %r42;
    mul.lo.s32 %r118, %r118, %r74;
    add.s32 %r119, %r118, %r83;
    add.s32 %r120, %r119, %r113;
    cvt.s64.s32 %rd30, %r120;
    shl.b64 %rd31, %rd30, 2;
    add.s64 %rd32, %rd4, %rd31;
    ld.global.f32 %f18, [%rd32];

L_LOADW_SKIP:
    shl.b32 %r121, %r110, 2;
    add.s32 %r122, %r73, %r121;
    st.shared.f32 [%r122], %f18;

    add.s32 %r110, %r110, 256;
    bra.uni L_LOADW_LOOP;
L_LOADW_END:

    bar.sync 0;

    @!%p3 bra L_COMPUTE_SKIP;

    mul.lo.s32 %r130, %r2, %r36;
    mul.lo.s32 %r131, %r3, %r36;

    mov.s32 %r132, 0;
L_KH_LOOP:
    setp.ge.s32 %p15, %r132, %r35;
    @%p15 bra L_KH_END;

    mul.lo.s32 %r133, %r132, %r38;
    add.s32 %r134, %r130, %r133;

    mov.s32 %r135, 0;
L_KW_LOOP:
    setp.ge.s32 %p16, %r135, %r35;
    @%p16 bra L_KW_END;

    mul.lo.s32 %r136, %r135, %r38;
    add.s32 %r137, %r131, %r136;

    mul.lo.s32 %r138, %r134, %r47;
    add.s32 %r138, %r138, %r137;
    shl.b32 %r139, %r138, 2;
    add.s32 %r140, %r72, %r139;
    ld.shared.f32 %f19, [%r140];

