    add.s32 %r151, %r150, %r141;
    shl.b32 %r152, %r151, 2;
    add.s32 %r153, %r73, %r152;
    ld.shared.f32 %f20, [%r153];
    fma.rn.f32 %f4, %f19, %f20, %f4;

    mul.lo.s32 %r150, %r74, 4;
    add.s32 %r151, %r150, %r141;
    shl.b32 %r152, %r151, 2;
    add.s32 %r153, %r73, %r152;
    ld.shared.f32 %f20, [%r153];
    fma.rn.f32 %f5, %f19, %f20, %f5;

    mul.lo.s32 %r150, %r74, 5;
    add.s32 %r151, %r150, %r141;
