_MODULE = None


def _get_module():
    global _MODULE
    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Look up the kernel entry point to validate the PTX module compiles
    and exposes the expected symbol."""
    module = _get_module()
    fn = module.function("conv2d_kernel")
    assert fn is not None, "conv2d_kernel entry not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    Standard 2D convolution implemented with a hand-authored PTX kernel
    that mirrors the cooperative-tiled CuTe/CUDA reference implementation,
    with an added IC_TILE=4 channel-group optimization that stages four
    input channels' worth of shared-memory data per synchronization round
    to reduce barrier overhead and increase shared-memory reuse.
    """

    TILE_OH = 16
    TILE_OW = 16
    OC_TILE = 16
    IC_TILE = 4

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        K = self.kernel_size
        Cin_g = self.in_channels // self.groups

        self.weight = nn.Parameter(torch.empty(self.out_channels, Cin_g, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        x = x.contiguous().to(torch.float32)
        w = self.weight.contiguous().to(torch.float32)

        N, Cin, H, Win = (int(s) for s in x.shape)
        Cout, Cin_g, K, K2 = (int(s) for s in w.shape)
        assert K == K2, "kernel must be square"

        stride = self.stride
        padding = self.padding
        dilation = self.dilation
        groups = self.groups

        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        assert Hout > 0 and Wout > 0

        Cout_g = Cout // groups
        num_oc_tiles_per_group = (Cout_g + self.OC_TILE - 1) // self.OC_TILE
        total_oc_tiles = groups * num_oc_tiles_per_group

        halo_h = (self.TILE_OH - 1) * stride + (K - 1) * dilation + 1
        halo_w = (self.TILE_OW - 1) * stride + (K - 1) * dilation + 1

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=torch.float32)

        has_bias = 1 if self.bias is not None else 0
        if self.bias is not None:
            b = self.bias.contiguous().to(torch.float32)
        else:
            # dummy valid pointer; never dereferenced when has_bias == 0
            b = w

        grid_x = (Wout + self.TILE_OW - 1) // self.TILE_OW
        grid_y = (Hout + self.TILE_OH - 1) // self.TILE_OH
        grid_z = N * total_oc_tiles

        # Shared memory now holds IC_TILE input-channel halo tiles plus
        # IC_TILE weight slices, staged once per synchronization round.
        shared_bytes = (self.IC_TILE * halo_h * halo_w +
                         self.IC_TILE * self.OC_TILE * K * K) * 4

        module = _get_module()
        fn = module.function("conv2d_kernel")

        stream = torch.cuda.current_stream(x.device).cuda_stream

        module.launch(
            fn,
            grid=(grid_x, grid_y, grid_z),
            block=(self.TILE_OH * self.TILE_OW, 1, 1),
            shared_mem_bytes=shared_bytes,
            stream=stream,
            args=[
                u64(x.data_ptr()),
                u64(w.data_ptr()),
                u64(b.data_ptr()),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(H), i32(Win),
                i32(Cout), i32(K), i32(stride), i32(padding),
                i32(dilation), i32(groups), i32(Hout), i32(Wout),
                i32(Cin_g), i32(Cout_g), i32(num_oc_tiles_per_group),
                i32(total_oc_tiles), i32(halo_h), i32(halo_w), i32(has_bias),
            ],
        )

        return y

import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the same cooperative-tiled 2D convolution
# algorithm as the reference CuTe/CUDA kernel, extended with an IC_TILE=4
# channel-group optimization: instead of synchronizing threads once per
# single input channel (load -> sync -> compute -> sync), the kernel now
# stages IC_TILE=4 input channels' halo tiles and weight slices into shared
# memory per outer-loop iteration, amortizing barrier synchronization cost
# and increasing shared-memory reuse per sync round:
#   - 16x16 spatial output tile per block (256 threads)
#   - OC_TILE = 16 output channels per block
#   - IC_TILE = 4 input channels staged per shared-memory round
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.extern .shared .align 4 .b8 smem[];

.visible .entry conv2d_kernel(
    .param .u64 X_ptr,
    .param .u64 W_ptr,
    .param .u64 B_ptr,
    .param .u64 Y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation,
    .param .u32 groups,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 Cin_g,
    .param .u32 Cout_g,
    .param .u32 num_oc_tiles_per_group,
    .param .u32 total_oc_tiles,
    .param .u32 halo_h,
    .param .u32 halo_w,
    .param .u32 has_bias
)
{
    .reg .pred  %p<50>;
    .reg .b32   %r<260>;
    .reg .f32   %f<32>;
    .reg .b64   %rd<60>;

    // ---- load pointers ----
    ld.param.u64 %rd1, [X_ptr];
    cvta.to.global.u64 %rd2, %rd1;
    ld.param.u64 %rd3, [W_ptr];
    cvta.to.global.u64 %rd4, %rd3;
    ld.param.u64 %rd5, [B_ptr];
    cvta.to.global.u64 %rd6, %rd5;
    ld.param.u64 %rd7, [Y_ptr];
    cvta.to.global.u64 %rd8, %rd7;

    // ---- load scalars ----
    ld.param.u32 %r30, [N];
    ld.param.u32 %r31, [Cin];
    ld.param.u32 %r32, [H];
    ld.param.u32 %r33, [Win];
    ld.param.u32 %r34, [Cout];
    ld.param.u32 %r35, [K];
    ld.param.u32 %r36, [stride];
    ld.param.u32 %r37, [padding];
    ld.param.u32 %r38, [dilation];
    ld.param.u32 %r39, [groups];
    ld.param.u32 %r40, [Hout];
    ld.param.u32 %r41, [Wout];
    ld.param.u32 %r42, [Cin_g];
    ld.param.u32 %r43, [Cout_g];
    ld.param.u32 %r44, [num_oc_tiles_per_group];
    ld.param.u32 %r45, [total_oc_tiles];
    ld.param.u32 %r46, [halo_h];
    ld.param.u32 %r47, [halo_w];
    ld.param.u32 %r48, [has_bias];

    setp.ne.s32 %p17, %r48, 0;

    // ---- thread indices within 16x16 tile ----
    mov.u32 %r1, %tid.x;
    shr.u32 %r2, %r1, 4;
    and.b32 %r3, %r1, 15;

    // ---- decode blockIdx.z -> (n, group, oc_tile) ----
    mov.u32 %r4, %ctaid.z;
    div.s32 %r5, %r4, %r45;
    mul.lo.s32 %r6, %r5, %r45;
    sub.s32 %r7, %r4, %r6;

    div.s32 %r8, %r7, %r44;
    mul.lo.s32 %r9, %r8, %r44;
    sub.s32 %r10, %r7, %r9;

    shl.b32 %r11, %r10, 4;

    mul.lo.s32 %r12, %r8, %r43;
    add.s32 %r13, %r12, %r11;

    sub.s32 %r14, %r43, %r11;
    min.s32 %r15, %r14, 16;

    // ---- spatial tile origin & output coords ----
    mov.u32 %r16, %ctaid.y;
    shl.b32 %r17, %r16, 4;
    mov.u32 %r18, %ctaid.x;
    shl.b32 %r19, %r18, 4;

    add.s32 %r20, %r17, %r2;
    add.s32 %r21, %r19, %r3;

    setp.lt.s32 %p1, %r20, %r40;
    setp.lt.s32 %p2, %r21, %r41;
    and.pred  %p3, %p1, %p2;

    // ---- ih_base, iw_base ----
    mul.lo.s32 %r53, %r17, %r36;
    sub.s32 %r50, %r53, %r37;
    mul.lo.s32 %r54, %r19, %r36;
    sub.s32 %r51, %r54, %r37;

    // ---- ic_base ----
    mul.lo.s32 %r52, %r8, %r42;

    // ---- X batch pointer ----
    mul.lo.s32 %r60, %r31, %r32;
    mul.lo.s32 %r61, %r60, %r33;
    mul.wide.s32 %rd10, %r5, %r61;
    shl.b64 %rd11, %rd10, 2;
    add.s64 %rd12, %rd2, %rd11;

