    mul.lo.s32 %r62, %r34, %r40;
    mul.lo.s32 %r63, %r62, %r41;
    mul.wide.s32 %rd13, %r5, %r63;
    shl.b64 %rd14, %rd13, 2;
    add.s64 %rd15, %rd8, %rd14;

    // ---- shared memory layout (IC_TILE = 4 channels staged per round) ----
    mul.lo.s32 %r70, %r46, %r47;      // halo_h*halo_w  (per-channel X elems)
    shl.b32 %r71, %r70, 4;            // bytes for IC_TILE(4)*r70*4
