    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Look up the kernel entry point to validate the PTX module compiles
    and exposes the expected symbol."""
    module = _get_module()
    fn = module.function("conv2d_kernel")
    assert fn is not None, "conv2d_kernel entry not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    Standard 2D convolution implemented with a hand-authored PTX kernel
    that mirrors the cooperative-tiled CuTe/CUDA reference implementation,
    with double-buffered (cp.async-pipelined) shared-memory staging of the
    input-channel tiles to overlap global memory latency with compute.
    """

    TILE_OH = 16
    TILE_OW = 16
    OC_TILE = 16

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        K = self.kernel_size
        Cin_g = self.in_channels // self.groups

        self.weight = nn.Parameter(torch.empty(self.out_channels, Cin_g, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        x = x.contiguous().to(torch.float32)
        w = self.weight.contiguous().to(torch.float32)

        N, Cin, H, Win = (int(s) for s in x.shape)
        Cout, Cin_g, K, K2 = (int(s) for s in w.shape)
        assert K == K2, "kernel must be square"

        stride = self.stride
        padding = self.padding
        dilation = self.dilation
        groups = self.groups

        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        assert Hout > 0 and Wout > 0

        Cout_g = Cout // groups
        num_oc_tiles_per_group = (Cout_g + self.OC_TILE - 1) // self.OC_TILE
        total_oc_tiles = groups * num_oc_tiles_per_group

        halo_h = (self.TILE_OH - 1) * stride + (K - 1) * dilation + 1
        halo_w = (self.TILE_OW - 1) * stride + (K - 1) * dilation + 1

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=torch.float32)

        has_bias = 1 if self.bias is not None else 0
        if self.bias is not None:
            b = self.bias.contiguous().to(torch.float32)
        else:
            # dummy valid pointer; never dereferenced when has_bias == 0
            b = w

        grid_x = (Wout + self.TILE_OW - 1) // self.TILE_OW
        grid_y = (Hout + self.TILE_OH - 1) // self.TILE_OH
        grid_z = N * total_oc_tiles

        # Double-buffered shared memory: two copies of (input halo tile + weight tile)
        shared_bytes = 2 * (halo_h * halo_w + self.OC_TILE * K * K) * 4

        module = _get_module()
        stream = torch.cuda.current_stream(x.device).cuda_stream
        module.launch(
            "conv2d_kernel",
            grid=(grid_x, grid_y, grid_z),
            block=(self.TILE_OH * self.TILE_OW, 1, 1),
            shared=shared_bytes,
            stream=stream,
            args=[
                u64(x.data_ptr()),
                u64(w.data_ptr()),
                u64(b.data_ptr()),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(H), i32(Win),
                i32(Cout), i32(K), i32(stride), i32(padding),
                i32(dilation), i32(groups), i32(Hout), i32(Wout),
                i32(Cin_g), i32(Cout_g), i32(num_oc_tiles_per_group),
                i32(total_oc_tiles), i32(halo_h), i32(halo_w), i32(has_bias),
            ],
        )

        return y

