    mov.u32 %r16, %ctaid.y;
    shl.b32 %r17, %r16, 4;
    mov.u32 %r18, %ctaid.x;
    shl.b32 %r19, %r18, 4;

    add.s32 %r20, %r17, %r2;
    add.s32 %r21, %r19, %r3;

    setp.lt.s32 %p1, %r20, %r40;
    setp.lt.s32 %p2, %r21, %r41;
    and.pred  %p3, %p1, %p2;

    // ---- ih_base, iw_base ----
    mul.lo.s32 %r53, %r17, %r36;
    sub.s32 %r50, %r53, %r37;
    mul.lo.s32 %r54, %r19, %r36;
    sub.s32 %r51, %r54, %r37;

